68	// "A building block of 3 alike components is offered at a special base premium of 60 G."
69	const COMPONENT_TYPES = ["rune", "moonstone"];
70	const BLOCK_SIZE = 3;
71	const COMPONENT_BLOCK_PREMIUM = 60;
72	
73	const isCursed = (item: QuoteItem): boolean => item.cursed === true;
74	
75	const isHighlyEnchanted = (item: QuoteItem): boolean =>
76	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
77	
78	// Surcharges apply per item, as a percentage of that item's base premium.
79	const surchargeOn = (
80	  items: QuoteItem[],
81	  applies: (item: QuoteItem) => boolean,
82	  rate: number,
83	): number =>
84	  items.reduce(
85	    (sum, item) => sum + (applies(item) ? BASE_PREMIUMS[item.type] * rate : 0),
86	    0,
87	  );
88	
89	const quotePremium = (items: QuoteItem[], customer: Customer): number => {
90	  const itemBase = items.reduce(
91	    (sum, item) => sum + BASE_PREMIUMS[item.type],
92	    0,
93	  );
94	  const blockDiscount = COMPONENT_TYPES.reduce((discount, type) => {
95	    const count = items.filter((item) => item.type === type).length;
96	    return count === BLOCK_SIZE
97	      ? discount + BLOCK_SIZE * BASE_PREMIUMS[type] - COMPONENT_BLOCK_PREMIUM
98	      : discount;
99	  }, 0);
100	  const policyBase = itemBase - blockDiscount;
101	  const curseSurcharge = surchargeOn(items, isCursed, CURSE_SURCHARGE_RATE);
102	  const highEnchantmentSurcharge = surchargeOn(
103	    items,
104	    isHighlyEnchanted,
105	    HIGH_ENCHANTMENT_SURCHARGE_RATE,
106	  );
107	  const firstInsurance = policyBase * FIRST_INSURANCE_RATE;
108	  const loyaltyDiscount =
109	    customer.yearsWithMHPCO >= 2 ? policyBase * 0.2 : 0;
110	  return Math.ceil(
111	    policyBase +
112	      curseSurcharge +
113	      highEnchantmentSurcharge +
114	      firstInsurance -
115	      loyaltyDiscount +
116	      PROCESSING_FEE,
117	  );
118	};
119	
120	export const runScenario = (scenario: Scenario): ScenarioOutput => {
121	  const quote = scenario.steps[0] as QuoteStep;
122	  return {
123	    results: [{ premium: quotePremium(quote.items, scenario.customer) }],
124	  };
125	};
